private fun symbol(name: String, mirrored: Boolean, path: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
        autoMirror = mirrored
    )
        .addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
        .build()
